import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { avatarSubtitleCSS } from './Subtitle.sty.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';
import { textStyleCSS } from '../../styles/textStyle.sty.js';

//#region Typings
/** Accepted properties for the Avatar Subtitle */
export interface AvatarSubtitleProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the Avatar Subtitle slot. */
  children: React.ReactNode;
}
//#endregion

/** Avatar Subtitle component */
export const Subtitle = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  AvatarSubtitleProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: AvatarSubtitleProps = props;
  const childIsText = _isStringChildren(children);

  return (
    // eslint-disable-next-line react/jsx-no-useless-fragment
    <>
      {childIsText ? (
        <div
          data-testid={dataTestId}
          ref={forwardedRef}
          className={clsx(
            consumerClassName,
            avatarSubtitleCSS,
            textStyleCSS({ textStyle: 'small' }),
          )}
          style={consumerStyle}
        >
          {children}
        </div>
      ) : (
        <div
          data-testid={dataTestId}
          ref={forwardedRef}
          className={consumerClassName}
          style={consumerStyle}
        >
          {children}
        </div>
      )}
    </>
  );
});

(Subtitle as typeof Subtitle & { displayName: string }).displayName =
  'Avatar.Subtitle';
